INSERT INTO `task_info_code` (`task_info_id`,`task_info_code`,`task_info_name`,`is_latest`,`role_list`,`message_start`,`message_finish`,`message_suspend`,`transfer_pass`,`param_query`,`insert_user_id`,`insert_user_code`,`insert_user_name`,`insert_timestamp`,`delete_user_id`,`delete_user_code`,`delete_user_name`,`delete_timestamp`) VALUES (390,390,'関連者コード移動申請',1,'manager','表題関連者コード移動申請作業が行われたのでお知らせします。\n※この操作がご自身に身に覚えのない操作であっても、\nサイト運営者がデータの整合性から関連者コード併合申請を行うことがあります。\n\n下記のページからコード移行申請内容の確認を行ってください。\n\nトップページ > 運営者メニュー > 組織所属招待承諾登録\n\n【transferPass】\n\n※例えば、同姓同名の人と間違われているなどで、\n関連者コード併合に異議がある場合\nお問い合わせから運営者に連絡を取ってください。\n\nトップページ > 共通メニュー > 運営者に連絡を取る(自分自身)\n\n-------------\n\n政治資金関連者標準化サイト\nhttps://normalize-jp-seijishikin.net/\n','(未使用)','表題指定作業が中断しました。\n \n複数回試行しても処理できず、原因確認を依頼する場合は\n\n共通メニュー > 運営者に連絡を取る(自分自身)\n\nよりお問い合わせいただきますようお願いします。\n \n-------------\n \n政治資金関連者標準化サイト\nhttps://normalize-jp-seijishikin.net/\n','/move-code-myself','',201,1,'aaa','2026-11-03 15:23:04',0,0,'','1948-07-28 23:59:59');
INSERT INTO `task_info_code` (`task_info_id`,`task_info_code`,`task_info_name`,`is_latest`,`role_list`,`message_start`,`message_finish`,`message_suspend`,`transfer_pass`,`param_query`,`insert_user_id`,`insert_user_code`,`insert_user_name`,`insert_timestamp`,`delete_user_id`,`delete_user_code`,`delete_user_name`,`delete_timestamp`) VALUES (391,391,'関連者コード移動結果',1,'','表題関連者コード移動判定が行われたのでお知らせします。\n※この操作がご自身に身に覚えのない操作であっても、\nサイト運営者がデータの整合性から関連者コード併合移動を行うことがあります。\n\n下記のページからコード移行申請内容の確認を行ってください。\n\nトップページ > 運営者メニュー > 組織所属招待承諾登録\n\n【transferPass】\n\n※コード変更申請連絡を美濃が下なので\n関連者コード併合に異議がある場合\nお問い合わせから運営者に連絡を取ってください。\n\nトップページ > 共通メニュー > 運営者に連絡を取る(自分自身)\n\n-------------\n\n政治資金関連者標準化サイト\nhttps://normalize-jp-seijishikin.net/\n','(未使用)','表題指定作業が中断しました。\n \n複数回試行しても処理できず、原因確認を依頼する場合は\n\n共通メニュー > 運営者に連絡を取る(自分自身)\n\nよりお問い合わせいただきますようお願いします。\n \n-------------\n \n政治資金関連者標準化サイト\nhttps://normalize-jp-seijishikin.net/\n','/move-code-myself','',201,1,'aaa','2026-11-03 15:25:36',0,0,'','1948-07-28 23:59:59');
INSERT INTO `task_info_code` (`task_info_id`,`task_info_code`,`task_info_name`,`is_latest`,`role_list`,`message_start`,`message_finish`,`message_suspend`,`transfer_pass`,`param_query`,`insert_user_id`,`insert_user_code`,`insert_user_name`,`insert_timestamp`,`delete_user_id`,`delete_user_code`,`delete_user_name`,`delete_timestamp`) VALUES (401,401,'APIパートナー長期トークン期限切れ通知',1,'admin','表題の通り、API接続用長期トークン期限が近づいてきました。\n\n下記よりアクセスしてあらたな期限のトークンを発行してください。\n\nトップページ > APIパートナー > APIパートナー長期トークン(再)発行\n\n【transferPass】\n\n-------------\n\n政治資金関連者標準化サイト\nhttps://normalize-jp-seijishikin.net/\n','表題指定作業が終了しました。\n\n-------------\n \n政治資金関連者標準化サイト\nhttps://normalize-jp-seijishikin.net/\n','表題指定作業が中断しました。\n \n複数回試行しても処理できず、原因確認を依頼する場合は\n\n共通メニュー > 運営者に連絡を取る(自分自身)\n\nよりお問い合わせいただきますようお願いします。\n \n-------------\n \n政治資金関連者標準化サイト\nhttps://normalize-jp-seijishikin.net/\n','/partner-api/token-replace','',201,1,'aaa','2026-11-03 14:10:01',0,0,'','1948-07-28 23:59:59');
